mapper.select:
select inv.*, sp.selling_price as selling_price,
    sp.min_selling_price as min_selling_price, sp.max_selling_price as max_selling_price,
    sp.id as shop_price_id
from (

     and inv.item_id = #{itemId} 


             and inv.stock > 0 
             and inv.stock = 0 


     and item.name like concat('%', #{keyword}, '%') 
    order by item.sort_order asc, item.id desc
) inv

select inv.*, sp.selling_price as selling_price,
    sp.min_selling_price as min_selling_price, sp.max_selling_price as max_selling_price,
    sp.id as shop_price_id
from (

    order by item.sort_order asc, item.id desc
) inv
